package app.gtdial.lab;

import org.json.JSONArray;
import org.json.JSONObject;
import java.util.HashSet;
import java.util.Set;

/** Server schema is also checked locally; one bad claim rejects the entire response. */
final class AnalysisResponseValidator {
    static JSONObject schema(){return NutritionModels.parseObject(SCHEMA);}
    static JSONObject validate(JSONObject response,AnalysisSnapshot snapshot){validateSchema(response,schema(),0);JSONArray domains=response.optJSONArray("domains");Set<String> names=new HashSet<>();int narrative=0;JSONObject evidence=snapshot.evidence();for(int i=0;i<domains.length();i++){JSONObject domain=domains.optJSONObject(i);String name=domain.optString("domain"),status=domain.optString("status");if(!snapshot.selection().domains.contains(name)||!names.add(name)||rank(status)>rank(snapshot.ceilings.get(name)))throw new IllegalArgumentException("ANALYSIS_DOMAIN_OR_QUALITY");JSONArray observations=domain.optJSONArray("observations"),suggestions=domain.optJSONArray("suggestions");if("INSUFFICIENT".equals(status)&&(observations.length()>0||suggestions.length()>0))throw new IllegalArgumentException("INSUFFICIENT_CLAIMS");boolean compared=false;for(int j=0;j<observations.length();j++){JSONObject claim=observations.optJSONObject(j);compared|=refs(claim.optJSONArray("evidenceRefs"),name,evidence,false,trend(claim.optString("statement")));narrative+=claim.optString("statement").length();}for(int j=0;j<suggestions.length();j++){JSONObject claim=suggestions.optJSONObject(j);compared|=refs(claim.optJSONArray("evidenceRefs"),name,evidence,false,trend(claim.optString("action")+" "+claim.optString("rationale")));narrative+=claim.optString("action").length()+claim.optString("rationale").length();}if(trend(domain.optString("summary"))&&!compared)throw new IllegalArgumentException("COMPARISON_REFERENCE_REQUIRED");narrative+=domain.optString("summary").length();JSONArray limitations=domain.optJSONArray("limitations");for(int j=0;j<limitations.length();j++)narrative+=limitations.optString(j).length();}if(!names.equals(new HashSet<>(snapshot.selection().domains)))throw new IllegalArgumentException("ANALYSIS_DOMAIN_SET");JSONArray combined=response.optJSONArray("combined");for(int i=0;i<combined.length();i++){JSONObject claim=combined.optJSONObject(i);refs(claim.optJSONArray("evidenceRefs"),null,evidence,true,trend(claim.optString("statement")));narrative+=claim.optString("statement").length();}if(narrative>4500)throw new IllegalArgumentException("NARRATIVE_LIMIT");return NutritionModels.copy(response);}
    private static int rank(String quality){return "SUFFICIENT".equals(quality)?2:"LIMITED".equals(quality)?1:0;}
    // A lexical guard helps reject unsupported trends; it does not prove the truth of generated prose.
    private static boolean trend(String text){return text.toLowerCase(java.util.Locale.ROOT).matches("(?s).*(измен|вырос|сниз|увелич|уменьш|динамик|раньше|предыдущ|чаще|реже|increase|decrease|previous|trend).*");}
    private static boolean refs(JSONArray refs,String domain,JSONObject evidence,boolean combined,boolean comparative){Set<String> domains=new HashSet<>();boolean comparison=false,pair=false;for(int i=0;i<refs.length();i++){String id=refs.optString(i);JSONObject metric=evidence.optJSONObject(id);if(metric==null)throw new IllegalArgumentException("UNKNOWN_OR_NULL_EVIDENCE");if(id.startsWith("paired.")){if(!combined)throw new IllegalArgumentException("DOMAIN_PAIRED_REF");JSONArray names=metric.optJSONArray("domains");for(int j=0;j<names.length();j++)domains.add(names.optString(j));pair=true;}else{String prefix=id.substring(0,id.indexOf('.'));if(domain!=null&&!domain.equals(prefix))throw new IllegalArgumentException("CROSS_DOMAIN_REF");domains.add(prefix);if(id.contains(".comparison.")||id.endsWith(".changeKg"))comparison=true;}}if(combined&&(!pair||domains.size()<2))throw new IllegalArgumentException("PAIRED_REFERENCE_REQUIRED");if(comparative&&!comparison)throw new IllegalArgumentException("COMPARISON_REFERENCE_REQUIRED");return comparison;}
    static void validateSchema(Object value,JSONObject schema,int depth){if(depth>32)throw new IllegalArgumentException("SCHEMA_DEPTH");Object type=schema.opt("type");boolean accepted=false;if(type instanceof JSONArray){JSONArray types=(JSONArray)type;for(int i=0;i<types.length();i++)accepted|=type(value,types.optString(i));}else accepted=type(value,String.valueOf(type));if(!accepted)throw new IllegalArgumentException("RESPONSE_TYPE");JSONArray enumeration=schema.optJSONArray("enum");if(enumeration!=null){boolean match=false;for(int i=0;i<enumeration.length();i++)if(NutritionModels.canonical(value).equals(NutritionModels.canonical(enumeration.opt(i))))match=true;if(!match)throw new IllegalArgumentException("RESPONSE_ENUM");}if(value==null||value==JSONObject.NULL)return;
        if(value instanceof JSONObject){JSONObject object=(JSONObject)value,properties=schema.optJSONObject("properties");JSONArray required=schema.optJSONArray("required");if(required!=null)for(int i=0;i<required.length();i++)if(!object.has(required.optString(i)))throw new IllegalArgumentException("RESPONSE_REQUIRED");for(String key:NutritionModels.fieldNames(object)){JSONObject child=properties==null?null:properties.optJSONObject(key);if(child==null){if(!schema.optBoolean("additionalProperties",true))throw new IllegalArgumentException("RESPONSE_UNKNOWN_FIELD");}else validateSchema(object.opt(key),child,depth+1);}}
        else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;if(a.length()<schema.optInt("minItems",0)||a.length()>schema.optInt("maxItems",Integer.MAX_VALUE))throw new IllegalArgumentException("RESPONSE_ARRAY_LIMIT");Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++){if(schema.optBoolean("uniqueItems")&&!seen.add(NutritionModels.canonical(a.opt(i))))throw new IllegalArgumentException("RESPONSE_DUPLICATE");JSONObject item=schema.optJSONObject("items");if(item!=null)validateSchema(a.opt(i),item,depth+1);}}
        else if(value instanceof String){int n=((String)value).length();if(n<schema.optInt("minLength",0)||n>schema.optInt("maxLength",Integer.MAX_VALUE)||n>0&&((String)value).trim().isEmpty())throw new IllegalArgumentException("RESPONSE_STRING_LIMIT");}
        else if(value instanceof Number){double n=((Number)value).doubleValue();if(!Double.isFinite(n)||schema.has("minimum")&&n<schema.optDouble("minimum")||schema.has("maximum")&&n>schema.optDouble("maximum"))throw new IllegalArgumentException("RESPONSE_NUMBER_LIMIT");}}
    private static boolean type(Object v,String type){switch(type){case "null":return v==null||v==JSONObject.NULL;case "object":return v instanceof JSONObject;case "array":return v instanceof JSONArray;case "string":return v instanceof String;case "integer":return v instanceof Integer||v instanceof Long;case "number":return v instanceof Number&&Double.isFinite(((Number)v).doubleValue());case "boolean":return v instanceof Boolean;default:return false;}}
    private static final String SCHEMA="{\"type\":\"object\",\"properties\":{\"schemaVersion\":{\"type\":\"integer\",\"enum\":[1]},\"domains\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":7,\"items\":{\"type\":\"object\",\"properties\":{\"domain\":{\"type\":\"string\",\"enum\":[\"nutrition\",\"activity\",\"sleep\",\"heart\",\"spo2\",\"strength\",\"weight\"]},\"status\":{\"type\":\"string\",\"enum\":[\"SUFFICIENT\",\"LIMITED\",\"INSUFFICIENT\"]},\"summary\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":280},\"observations\":{\"type\":\"array\",\"maxItems\":2,\"items\":{\"type\":\"object\",\"properties\":{\"statement\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200},\"evidenceRefs\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":4,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":100}}},\"required\":[\"statement\",\"evidenceRefs\"],\"additionalProperties\":false}},\"suggestions\":{\"type\":\"array\",\"maxItems\":2,\"items\":{\"type\":\"object\",\"properties\":{\"action\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":180},\"rationale\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":180},\"evidenceRefs\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":4,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":100}}},\"required\":[\"action\",\"rationale\",\"evidenceRefs\"],\"additionalProperties\":false}},\"limitations\":{\"type\":\"array\",\"maxItems\":3,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":160}}},\"required\":[\"domain\",\"status\",\"summary\",\"observations\",\"suggestions\",\"limitations\"],\"additionalProperties\":false}},\"combined\":{\"type\":\"array\",\"maxItems\":3,\"items\":{\"type\":\"object\",\"properties\":{\"statement\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200},\"evidenceRefs\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":4,\"uniqueItems\":true,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":100}}},\"required\":[\"statement\",\"evidenceRefs\"],\"additionalProperties\":false}}},\"required\":[\"schemaVersion\",\"domains\",\"combined\"],\"additionalProperties\":false}";
    private AnalysisResponseValidator(){}
}



